CREATE TABLE IF NOT EXISTS users (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role ENUM('solicitante','comprador','aprovador') NOT NULL);
CREATE TABLE IF NOT EXISTS suppliers (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(150) NOT NULL, document VARCHAR(30) NOT NULL, email VARCHAR(190) NOT NULL, phone VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS requests (id INT AUTO_INCREMENT PRIMARY KEY, title VARCHAR(150) NOT NULL, description TEXT NOT NULL, deadline DATE NOT NULL, status ENUM('aberta','em_aprovacao','aprovada','rejeitada') NOT NULL DEFAULT 'aberta', requester_id INT NOT NULL, selected_quote_id INT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (requester_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS quotes (id INT AUTO_INCREMENT PRIMARY KEY, request_id INT NOT NULL, supplier_id INT NOT NULL, amount_cents INT UNSIGNED NOT NULL, notes VARCHAR(500) NOT NULL DEFAULT '', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (request_id) REFERENCES requests(id), FOREIGN KEY (supplier_id) REFERENCES suppliers(id));
CREATE TABLE IF NOT EXISTS history (id INT AUTO_INCREMENT PRIMARY KEY, request_id INT NOT NULL, user_id INT NOT NULL, action VARCHAR(500) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (request_id) REFERENCES requests(id), FOREIGN KEY (user_id) REFERENCES users(id));
